rce":{"path":"OpenProblemLibrary/ASU-topics/setAlgebraFunctions/beth2algfun.pg","sha256":"a6470e62683d0331d541a5df7f8fe8cc4eaa31fba7886fef1a8e5ea24f1984ae","url":"https://github.com/openwebwork/webwork-open-problem-library/blob/0d42812d6d02960c846fc0f89215e0d4f1e761b1/OpenProblemLibrary/ASU-topics/setAlgebraFunctions/beth2algfun.pg","attribution":"No problem author declared in inspected source header; retained institution/path attribution.","repository":"https://github.com/openwebwork/webwork-open-problem-library","revision":"0d42812d6d02960c846fc0f89215e0d4f1e761b1","authors":[],"institution":"ASU","licenseEvidence":"OPL_LICENSE supplies a conditional default; individual and parent-directory notices still require review before redistribution or commercial use."}},{"legacyId":"compat-calculus-graph-01","title":"Read a function and derivative graph","description":"Read a graph and estimate a derivative.","subject":"Calculus - single variable","topic":"Derivatives from graphs","source":{"path":"OpenProblemLibrary/270/setDerivatives1/ur_dr_1_7.pg","sha256":"b91bc436c92c6d68434c522d5bac40087af07bf75019b058710173ea8d0ca053","url":"https://github.com/openwebwork/webwork-open-problem-library/blob/0d42812d6d02960c846fc0f89215e0d4f1e761b1/OpenProblemLibrary/270/setDerivatives1/ur_dr_1_7.pg","attribution":"No problem author declared in inspected source header; retained institution/path attribution.","repository":"https://github.com/openwebwork/webwork-open-problem-library","revision":"0d42812d6d02960c846fc0f89215e0d4f1e761b1","authors":[],"institution":null,"licenseEvidence":"OPL_LICENSE supplies a conditional default; individual and parent-directory notices still require review before redistribution or commercial use."}},{"legacyId":"compat-algebra-graphtool-01","title":"Plot points on a linear equation","description":"Plot points on a linear equation","subject":"Algebra","topic":"Algebra","source":{"path":"OpenProblemLibrary/PCC/BasicAlgebra/EquationsAndInequalitiesInTwoVariables/PlotMXPlusB.pg","sha256":"6c971d903bb786efb7869ed8f517a10f69646d9883e72c4d0e8e011cea4d8a4f","url":"https://github.com/openwebwork/webwork-open-problem-library/blob/0d42812d6d02960c846fc0f89215e0d4f1e761b1/OpenProblemLibrary/PCC/BasicAlgebra/EquationsAndInequalitiesInTwoVariables/PlotMXPlusB.pg","attribution":"As credited in source; textbook credits are not treated as problem authors.","repository":"https://github.com/openwebwork/webwork-open-problem-library","revision":"0d42812d6d02960c846fc0f89215e0d4f1e761b1","authors":["Alex Jordan"],"institution":null,"licenseEvidence":"OPL_LICENSE supplies a conditional default; individual and parent-directory notices still require review before redistribution or commercial use."}}]'::jsonb;item jsonb;repo uuid;snap uuid;exercise uuid;source uuid;release uuid;candidate uuid;old_hash text; BEGIN
 INSERT INTO catalog.repositories(registry_key,canonical_url) VALUES('openwebwork-opl','https://github.com/openwebwork/webwork-open-problem-library') ON CONFLICT(registry_key) DO NOTHING;
 SELECT id INTO repo FROM catalog.repositories WHERE registry_key='openwebwork-opl' AND canonical_url='https://github.com/openwebwork/webwork-open-problem-library';IF repo IS NULL THEN RAISE EXCEPTION 'Repository bootstrap conflict';END IF;
 INSERT INTO catalog.snapshots(repository_id,object_format,commit_oid) VALUES(repo,'sha1','0d42812d6d02960c846fc0f89215e0d4f1e761b1') ON CONFLICT(repository_id,object_format,commit_oid) DO NOTHING;
 SELECT id INTO snap FROM catalog.snapshots WHERE repository_id=repo AND object_format='sha1' AND commit_oid='0d42812d6d02960c846fc0f89215e0d4f1e761b1';
 INSERT INTO catalog.metadata_releases(release_key,state) VALUES('legacy-display-v1','draft') ON CONFLICT(release_key) DO NOTHING;SELECT id INTO release FROM catalog.metadata_releases WHERE release_key='legacy-display-v1';
 FOR item IN SELECT value FROM jsonb_array_elements(payload) LOOP
  SELECT exercise_id INTO exercise FROM catalog.aliases WHERE namespace='experimental-opl' AND external_id=item->>'legacyId';
  IF exercise IS NULL THEN INSERT INTO catalog.exercises(provider) VALUES('opl') RETURNING id INTO exercise;INSERT INTO catalog.aliases(namespace,external_id,exercise_id) VALUES('experimental-opl',item->>'legacyId',exercise);END IF;
  SELECT id,sha256 INTO source,old_hash FROM catalog.source_versions WHERE exercise_id=exercise AND snapshot_id=snap;
  IF source IS NULL THEN INSERT INTO catalog.source_versions(exercise_id,snapshot_id,path,sha256) VALUES(exercise,snap,item->'source'->>'path',item->'source'->>'sha256') RETURNING id INTO source;
  ELSIF old_hash IS DISTINCT FROM item->'source'->>'sha256' OR NOT EXISTS(SELECT 1 FROM catalog.source_versions WHERE id=source AND path=item->'source'->>'path') THEN RAISE EXCEPTION 'Source bootstrap conflict';END IF;
  IF NOT EXISTS(SELECT 1 FROM catalog.metadata_documents WHERE release_id=release AND exercise_id=exercise AND locale='en') THEN
   INSERT INTO catalog.metadata_candidates(source_version_id,field,locale,value,origin,reference,review_state) VALUES(source,'title','en',item->'title','legacy-catalog',jsonb_build_object('file','exercise-catalog.json','scope','display-only-not-new-PG-approval'),'approved') RETURNING id INTO candidate;
   INSERT INTO catalog.metadata_selections(release_id,exercise_id,source_version_id,snapshot_id,locale,field,candidate_id) VALUES(release,exercise,source,snap,'en','title',candidate);
   INSERT INTO catalog.metadata_documents(release_id,exercise_id,source_version_id,snapshot_id,locale,title,title_sort,description,subject_label,topic_label,attribution)
   VALUES(release,exercise,source,snap,'en',item->>'title',lower(normalize(item->>'title',NFKC)),item->>'description',item->>'subject',item->>'topic',jsonb_build_object('provider','WeBWorK Open Problem Library','contributors',item->'source'->'authors','institution',item->'source'->'institution','sourceUrl',item->'source'->>'url','licenseEvidence',item->'source'->>'licenseEvidence'));
  ELSIF NOT EXISTS(SELECT 1 FROM catalog.metadata_documents WHERE release_id=release AND exercise_id=exercise AND source_version_id=source AND title=item->>'title' AND description IS NOT DISTINCT FROM item->>'description') THEN RAISE EXCEPTION 'Display bootstrap conflict';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM catalog.metadata_releases WHERE id=release AND state='draft') THEN UPDATE catalog.metadata_releases SET state='published' WHERE id=release;END IF;
 INSERT INTO catalog.metadata_heads(scope,release_id,generation) VALUES('local-practice',release,0) ON CONFLICT(scope) DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM catalog.metadata_heads WHERE scope='local-practice' AND release_id=release) THEN RAISE EXCEPTION 'Metadata head conflict';END IF;
END $bootstrap$;
COMMIT;
